function validate([stations, k]) {
  if (!Array.isArray(stations) || stations.length < 10 || stations.length > 2000) return 'stations needs 10 to 2000 positions.';
  if (stations.some(v => !Number.isInteger(v) || v < 0 || v > 100000000)) return 'Each position is an integer from 0 to 10^8.';
  for (let i = 1; i < stations.length; i++) if (stations[i] <= stations[i - 1]) return 'stations must be strictly increasing.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000) return 'k is an integer from 1 to 10^6.';
  return null;
}

