function minmaxGasDist(stations, k) {
  let low = 0;
  let high = 0;
  for (let i = 1; i < stations.length; i++) {
    high = Math.max(high, stations[i] - stations[i - 1]);
  }

  for (let step = 0; step < 100; step++) {
    const mid = (low + high) / 2;
    let needed = 0;
    for (let i = 1; i < stations.length; i++) {
      needed += Math.ceil((stations[i] - stations[i - 1]) / mid) - 1;
    }
    if (needed <= k) {
      high = mid;
    } else {
      low = mid;
    }
  }
  return high;
}

