function minmaxGasDist(stations, k) {
  // Add the stations one at a time, always to the gap whose pieces are currently longest.
  const gaps = [];
  for (let i = 1; i < stations.length; i++) gaps.push(stations[i] - stations[i - 1]);
  const parts = gaps.map(() => 1);
  for (let added = 0; added < k; added++) {
    let worst = 0;
    for (let i = 1; i < gaps.length; i++) if (gaps[i] / parts[i] > gaps[worst] / parts[worst]) worst = i;
    parts[worst]++;
  }
  return Math.max(...gaps.map((gap, i) => gap / parts[i]));
}

