function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 10 + Math.floor(rand() * 4);
  const widest = size === 'large' ? (rand() < 0.5 ? 50000 : 100) : (rand() < 0.5 ? 20 : 3);
  const stations = [Math.floor(rand() * (size === 'large' ? 1000 : 5))];
  for (let i = 1; i < n; i++) stations.push(stations[i - 1] + 1 + Math.floor(rand() * widest));
  const k = size === 'large' ? 1 + Math.floor(rand() * 1000000) : 1 + Math.floor(rand() * 30);
  return [stations, k];
}
